Support for loading/saving JPEG XL files natively.

Benchmarks:

"test.jxl": A 1184 x 1776 full-color RGB JPEG XL image.

Benchmark code:

```c++
void bench_libjxl(benchmark::State &stat)
{
    for (auto _ : stat) {
        cimg_library::CImg<uint8_t> img;
        img.load_jxl("test.jxl");
    }
}
BENCHMARK(bench_libjxl);

void bench_load_other(benchmark::State &stat)
{
    for (auto _ : stat) {
        cimg_library::CImg<uint8_t> img;
        img.load_other("test.jxl");
    }
}
BENCHMARK(bench_load_other);

void bench_libjxl_save(benchmark::State &stat)
{
    cimg_library::CImg<uint8_t> img;
    img.load_jxl("test.jxl");
    for (auto _ : stat) {
        img.save_jxl("test2.jxl");
    }
}
BENCHMARK(bench_libjxl_save);

void bench_load_other(benchmark::State &stat)
{
    cimg_library::CImg<uint8_t> img;
    img.load_jxl("test.jxl");
    for (auto _ : stat) {
        img.save_other("test2.jxl");
    }
}
BENCHMARK(bench_load_other);
```

